SELECT rm.JOB_ID jobId , rm.JOB_STATUS jobStatus , rm.PRO_ID proId , rm.PRO_NAME proName , rm.END_DATE endDate , rm.NEXT_DATE nextDate, rj.JOB_NAME jobName, info.report_name reportName, DATE_FORMAT(rm.END_DATE,'%Y-%m-%d') endDateStr, DATE_FORMAT(rm.NEXT_DATE,'%Y-%m-%d') nextDateStr FROM rep_monitor rm left join rep_job rj on rj.JOB_ID = rm.JOB_ID LEFT JOIN rep_info info ON info.rep_id = rj.rep_id WHERE 1=1
AND rm.JOB_ID IN
#{item}
AND rm.PRO_ID IN
#{item}
AND DATE_FORMAT(rm.END_DATE,'%Y-%m-%d') >= #{valDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(rm.END_DATE,'%Y-%m-%d') <= #{valDateEnd,jdbcType=VARCHAR}

SELECT ril.JOB_ID jobId, ril.JOB_NAME jobName, ril.EXEC_STATUS execStatus, ril.EXEC_DATE execDate, DATE_FORMAT(ril.START_DATE,'%Y-%m-%d %h:%i:%s') startExecDate, DATE_FORMAT(ril.END_DATE,'%Y-%m-%d %h:%i:%s') endExecDate, ril.JOB_SEQ jobSeq, ril.EXEC_RESULT execResult, IFNULL(ril.EXEC_DETAIL,'') execResultExplain, DATE_FORMAT(ril.LASTEXEC_DATE,'%Y-%m-%d %h:%i:%s') lastexecDate
FROM REP_INSTALL_LOG ril WHERE ril.STATUS = #{status,jdbcType=VARCHAR}
AND ril.JOB_ID IN
#{item}
AND ril.EXEC_STATUS IN
#{item}
AND DATE_FORMAT(ril.START_DATE,'%Y-%m-%d') >= #{valDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(ril.START_DATE,'%Y-%m-%d') <= #{valDateEnd,jdbcType=VARCHAR}
AND ril.EXEC_RESULT IN
#{item}
order by ril.EXEC_STATUS,ril.UPDATE_TIME desc

